const profiles={maintenance:[900,680,8],storage:[900,640,7],video:[960,610,9],summary:[780,550,7],document:[820,610,8],browser:[900,620,7],files:[850,600,7],sources:[330,300,2],progress:[350,230,1],agents:[380,460,3],change:[740,570,6],note:[600,420,4]};
export class WindowManager {
 constructor(desktop,{render,onChange,onSound}){this.desktop=desktop;this.windows=new Map();this.z=30;this.focused=null;this.render=render;this.onChange=onChange;this.onSound=onSound;this.interacting=false;this.suspended=false;this.nativeSyncPending=false;this.userFocusUntil=0;this.dock=document.querySelector('#window-dock');desktop.addEventListener('pointerdown',()=>{this.userFocusUntil=performance.now()+5000},true);window.addEventListener('resize',()=>{for(const w of this.windows.values())this.fit(w);this.syncNative()})}
 defaults(kind){const b=this.bounds(),p=profiles[kind]||profiles.note;return {width:Math.min(p[0],b.width-20),height:Math.min(p[1],b.height-20),x:['sources','progress','agents'].includes(kind)?Math.max(0,b.width-p[0]-24):28,y:kind==='progress'?Math.max(0,b.height-p[1]-18):24}}
 bounds(){return {width:this.desktop.clientWidth,height:this.desktop.clientHeight}}
 open(spec,{actor='user'}={}){const id=spec.id||spec.kind+'-'+Date.now();if(this.windows.has(id)){const existing=this.windows.get(id);if(spec.title){existing.title=spec.title;existing.element.querySelector('.title-text').textContent=spec.title}if(spec.path&&spec.path!==existing.spec.path){existing.spec.path=spec.path;existing.body.replaceChildren();existing.ready=Promise.resolve(this.render(existing))}if(['x','y','width','height'].some(k=>Number.isFinite(spec[k])))this.move(id,spec);if(typeof spec.text==='string'&&spec.text!==existing.spec.text){existing.spec.text=spec.text;existing.body.replaceChildren();existing.ready=Promise.resolve(this.render(existing))}if(spec.url&&existing.address&&spec.url!==existing.spec.url){existing.spec.url=spec.url;existing.address.value=spec.url;window.argosDesktop?.browser({type:'open',id,url:spec.url}).catch(()=>{})}if(actor==='user')this.restore(id);this.changed();return id}const area=this.bounds(),n=this.windows.size;spec={...this.defaults(spec.kind),...spec};const w={id,kind:spec.kind,title:spec.title||spec.kind,x:spec.x??40+n*24,y:spec.y??22+n*20,width:spec.width??400,height:spec.height??320,minimized:false,maximized:false,actor,spec};const element=document.createElement('section');element.className='window';element.dataset.window=id;element.dataset.kind=w.kind;element.setAttribute('aria-label',w.title);const header=document.createElement('div');header.className='window-title';header.innerHTML='<span class="window-caption"><span class="kind"></span><span class="title-text"></span></span><span class="window-buttons"><button aria-label="Minimizar" title="Minimizar">−</button><button aria-label="Maximizar" title="Maximizar">□</button><button aria-label="Cerrar" title="Cerrar">×</button></span>';header.querySelector('.kind').textContent=String(n+1).padStart(2,'0')+' /';header.querySelector('.title-text').textContent=w.title;const body=document.createElement('div');body.className='window-body';const resize=document.createElement('div');resize.className='window-resize';resize.title='Redimensionar';element.append(header,body,resize);w.element=element;w.body=body;this.windows.set(id,w);this.desktop.append(element);header.querySelectorAll('button').forEach((b,i)=>b.onclick=()=>i===0?this.minimize(id):i===1?this.maximize(id):this.close(id));header.ondblclick=e=>{if(!e.target.closest('button'))this.maximize(id)};header.onpointerdown=e=>this.drag(w,e,false);resize.onpointerdown=e=>this.drag(w,e,true);element.onpointerdown=()=>this.focus(id);this.fit(w);w.ready=Promise.resolve(this.render(w));if(actor==='user'||w.kind==='change'||!this.focused||performance.now()>this.userFocusUntil)this.focus(id);else w.element.style.zIndex=10;this.onSound('open');this.changed();return id}
 fit(w){const b=this.bounds();w.width=Math.min(Math.max(270,w.width),b.width);w.height=Math.min(Math.max(150,w.height),b.height);w.x=Math.max(0,Math.min(w.x,b.width-w.width));w.y=Math.max(0,Math.min(w.y,b.height-40));if(w.maximized){w.x=0;w.y=0;w.width=b.width;w.height=b.height}Object.assign(w.element.style,{left:w.x+'px',top:w.y+'px',width:w.width+'px',height:w.height+'px'})}
 focus(id){const w=this.windows.get(id);if(!w||w.minimized)return;this.focused=id;for(const other of this.windows.values())other.element.classList.toggle('focused',other.id===id);w.element.style.zIndex=++this.z;this.syncNative();this.changed()}
 close(id){const w=this.windows.get(id);if(!w)return;w.resizeObserver?.disconnect();const closing=['browser','video'].includes(w.kind)?window.argosDesktop?.browser({type:'close',id}).catch(()=>{}):null;w.element.remove();this.windows.delete(id);if(this.focused===id){this.focused=null;const last=[...this.windows.values()].filter(w=>!w.minimized).at(-1);if(last)this.focus(last.id)}this.onSound('close');this.changed();this.syncNative();return closing}
 minimize(id){const w=this.windows.get(id);if(!w)return;w.minimized=true;w.element.classList.add('minimized');if(this.focused===id)this.focused=null;this.changed();this.syncNative()}
 restore(id){const w=this.windows.get(id);if(!w)return;w.minimized=false;w.element.classList.remove('minimized');this.focus(id);this.changed()}
 maximize(id){const w=this.windows.get(id);if(!w)return;if(w.maximized){Object.assign(w,w.previous);w.maximized=false}else{w.previous={x:w.x,y:w.y,width:w.width,height:w.height};w.maximized=true}w.element.classList.toggle('maximized',w.maximized);this.fit(w);this.focus(id);this.changed()}
 move(id,geometry){const w=this.windows.get(id);if(!w)return;for(const k of ['x','y','width','height'])if(Number.isFinite(geometry[k]))w[k]=geometry[k];w.maximized=false;w.userAdjusted=true;w.element.classList.remove('maximized');this.fit(w);this.syncNative();this.changed()}
 drag(w,e,resize){if(e.button!==0||e.target.closest('button')||w.maximized)return;e.preventDefault();this.focus(w.id);this.interacting=true;document.body.classList.add('interacting');w.element.classList.add('dragging');this.syncNative();const start={x:e.clientX,y:e.clientY,...{wx:w.x,wy:w.y,width:w.width,height:w.height}},handle=e.currentTarget;handle.setPointerCapture(e.pointerId);handle.onpointermove=event=>{const dx=event.clientX-start.x,dy=event.clientY-start.y;if(resize){w.width=start.width+dx;w.height=start.height+dy}else{w.x=start.wx+dx;w.y=start.wy+dy}this.fit(w)};const end=()=>{w.userAdjusted=true;this.interacting=false;document.body.classList.remove('interacting');w.element.classList.remove('dragging');handle.onpointermove=null;handle.onpointerup=null;handle.onpointercancel=null;this.syncNative();this.changed()};handle.onpointerup=end;handle.onpointercancel=end}
 arrange({automatic=false}={}){const visible=[...this.windows.values()].filter(w=>!w.minimized&&(!automatic||!w.userAdjusted)),b=this.bounds();if(!visible.length)return;const gap=12,weights=w=>(profiles[w.kind]||profiles.note)[2];
 const split=(items,box)=>{if(items.length===1){const w=items[0];w.maximized=false;w.element.classList.remove('maximized');Object.assign(w,box);if(['sources','progress','agents'].includes(w.kind))w.height=Math.min(w.height,(profiles[w.kind]||profiles.note)[1]);if(!automatic)w.userAdjusted=false;this.fit(w);return}const total=items.reduce((s,w)=>s+weights(w),0);let left=0,index=0;for(;index<items.length-1;index++){left+=weights(items[index]);if(left>=total*.48)break}index=Math.min(index+1,items.length-1);const vertical=box.width>box.height*1.25,ratio=left/total;let first,second;if(vertical){const size=(box.width-gap)*ratio;first={...box,width:size};second={...box,x:box.x+size+gap,width:box.width-size-gap}}else{const size=(box.height-gap)*ratio;first={...box,height:size};second={...box,y:box.y+size+gap,height:box.height-size-gap}}split(items.slice(0,index),first);split(items.slice(index),second)};
 const primary=visible.filter(w=>!['sources','progress','agents'].includes(w.kind)),side=visible.filter(w=>['sources','progress','agents'].includes(w.kind));
 if(primary.length&&side.length&&b.width>=850){const sw=Math.min(370,b.width*.25);split(primary,{x:16,y:12,width:b.width-sw-44,height:b.height-24});split(side,{x:b.width-sw-16,y:12,width:sw,height:b.height-24})}else split(visible,{x:16,y:12,width:b.width-32,height:b.height-24});this.syncNative();this.changed()}

 clear(){return Promise.all([...this.windows.keys()].map(id=>this.close(id)))}
 changed(){this.dock.replaceChildren();for(const w of this.windows.values())if(w.minimized){const button=document.createElement('button');button.textContent=w.title+' ↗';button.onclick=()=>this.restore(w.id);this.dock.append(button)}this.onChange(this.snapshot())}
 snapshot(){return [...this.windows.values()].map(w=>({id:w.id,kind:w.kind,title:w.title,x:w.x,y:w.y,width:w.width,height:w.height,minimized:w.minimized,maximized:w.maximized,actor:w.actor,focused:this.focused===w.id,...(w.spec.path?{path:w.spec.path}:{}),...(w.spec.selected_path?{selected_path:w.spec.selected_path}:{}),...(w.address?.value?{url:w.address.value}:{})}))}
 syncNative(){if(!window.argosDesktop||this.nativeSyncPending)return;this.nativeSyncPending=true;requestAnimationFrame(()=>{this.nativeSyncPending=false;const layouts=[];for(const w of this.windows.values())if(['browser','video'].includes(w.kind)&&w.browserHost){const rect=w.browserHost.getBoundingClientRect();layouts.push({id:w.id,visible:!w.minimized&&this.focused===w.id&&!this.interacting&&!this.suspended,x:Math.round(rect.x),y:Math.round(rect.y),width:Math.round(rect.width),height:Math.round(rect.height)})}window.argosDesktop.layout(layouts)})}
 suspend(value){this.suspended=value;this.syncNative()}
 apply(intent,{actor='argos'}={}){switch(intent.type){case'window.open':return this.open(intent,{actor});case'window.close':return this.close(intent.id);case'window.focus':return this.focus(intent.id);case'window.minimize':return this.minimize(intent.id);case'window.restore':return this.restore(intent.id);case'window.maximize':return this.maximize(intent.id);case'window.move':return this.move(intent.id,intent);case'workspace.arrange':return this.arrange();case'workspace.clear':return this.clear();case'window.update':{const w=this.windows.get(intent.id);if(w){if(typeof intent.title==='string'){w.title=intent.title;w.element.querySelector('.title-text').textContent=intent.title}if(typeof intent.text==='string'){w.spec.text=intent.text;const text=w.body.querySelector('.note-body');if(text)text.textContent=intent.text}if(typeof intent.status==='string'){const status=w.body.querySelector('.progress-copy');if(status)status.textContent=intent.status}this.changed()}return}default:throw Error('Unsupported presentation intent')}}
}
